type I18nContextValue = {
  language: Language;
  setLanguage: (language: Language) => void;
  t: (key: string, variables?: Variables) => string;
  locale: string;
};

const I18nContext = createContext<I18nContextValue | null>(null);
const storageKey = "utl-language";

function supportedLanguage(value: string | null | undefined): Language | null {
  const code = value?.toLowerCase().split("-")[0];
  return languages.some((language) => language.code === code) ? code as Language : null;
}

export function LanguageProvider({ children }: { children: React.ReactNode }) {
  const [language, setLanguageState] = useState<Language>("en");

  useEffect(() => {
    const saved = supportedLanguage(window.localStorage.getItem(storageKey));
    const detected = supportedLanguage(window.navigator.language);
    queueMicrotask(() => setLanguageState(saved || detected || "en"));
  }, []);

  useEffect(() => {
    document.documentElement.lang = language;
  }, [language]);

  const setLanguage = useCallback((next: Language) => {
    setLanguageState(next);
    try {
      window.localStorage.setItem(storageKey, next);
    } catch {
      // The language still changes for this session when storage is unavailable.
    }
  }, []);

  const t = useCallback((key: string, variables: Variables = {}) => {
    const template = language === "en" ? key : translations[language][key] || additionalTranslations[language][key] || key;
    return Object.entries(variables).reduce(
      (result, [name, value]) => result.replaceAll(`{${name}}`, String(value)),
      template,
    );
  }, [language]);

  return <I18nContext.Provider value={{ language, setLanguage, t, locale: `${language}-${language === "en" ? "GB" : language.toUpperCase()}` }}>{children}</I18nContext.Provider>;
}

export function useI18n() {
  const value = useContext(I18nContext);
  if (!value) throw new Error("useI18n must be used inside LanguageProvider");
  return value;
}
